CREATE TABLE pdf_artifact_reference (id INTEGER PRIMARY KEY, artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE pdf_filter_chain (id INTEGER PRIMARY KEY);
CREATE TABLE pdf_stream_filter (id INTEGER PRIMARY KEY, chain_id INTEGER NOT NULL REFERENCES pdf_filter_chain(id), ordinal INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('flate','lzw','asciiHex','ascii85','runLength','dct','jpx','ccitt','jbig2','crypt')), early_change INTEGER CHECK (early_change IN (0,1)), color_transform INTEGER, globals BLOB, crypt_name TEXT);
CREATE TABLE pdf_filter_predictor (id INTEGER PRIMARY KEY REFERENCES pdf_stream_filter(id), predictor INTEGER NOT NULL, colors INTEGER NOT NULL, bits_per_component INTEGER NOT NULL, columns INTEGER NOT NULL);
CREATE TABLE pdf_filter_ccitt (id INTEGER PRIMARY KEY REFERENCES pdf_stream_filter(id), k INTEGER NOT NULL, columns INTEGER NOT NULL, rows INTEGER NOT NULL, black_is_1 INTEGER NOT NULL CHECK (black_is_1 IN (0,1)), encoded_byte_align INTEGER NOT NULL CHECK (encoded_byte_align IN (0,1)), end_of_line INTEGER NOT NULL CHECK (end_of_line IN (0,1)), end_of_block INTEGER NOT NULL CHECK (end_of_block IN (0,1)), damaged_rows_before_error INTEGER NOT NULL);
CREATE TABLE pdf_cos_value (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('null','boolean','integer','decimal','string','name','array','dictionary','reference','stream','text','date')), boolean_value INTEGER CHECK (boolean_value IN (0,1)), integer_value INTEGER, negative INTEGER CHECK (negative IN (0,1)), coefficient TEXT, scale INTEGER, byte_string BLOB, name TEXT, reference_number INTEGER, reference_generation INTEGER, stream_data BLOB, filter_chain_id INTEGER REFERENCES pdf_filter_chain(id), date_id INTEGER REFERENCES pdf_date(id));
CREATE TABLE pdf_cos_array_element (id INTEGER PRIMARY KEY, array_id INTEGER NOT NULL REFERENCES pdf_cos_value(id), ordinal INTEGER NOT NULL, value_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));
CREATE TABLE pdf_cos_dictionary_entry (id INTEGER PRIMARY KEY, dictionary_id INTEGER NOT NULL REFERENCES pdf_cos_value(id), ordinal INTEGER NOT NULL, key TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));

CREATE TABLE pdf_function (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('sampled','exponential','stitching','postScript','array')), range_present INTEGER CHECK (range_present IN (0,1)), encode_present INTEGER CHECK (encode_present IN (0,1)), decode_present INTEGER CHECK (decode_present IN (0,1)), bits_per_sample INTEGER, interpolation_order INTEGER, exponent REAL, sample_count INTEGER, postscript_source TEXT, exponent_bits INTEGER, exponent_class TEXT CHECK (exponent_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_function_real (id INTEGER PRIMARY KEY, function_id INTEGER NOT NULL REFERENCES pdf_function(id), role TEXT NOT NULL CHECK (role IN ('domain','range','c0','c1','bounds','encode','decode')), ordinal INTEGER NOT NULL, value REAL, value_bits INTEGER, value_class TEXT CHECK (value_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_function_sample (id INTEGER PRIMARY KEY, function_id INTEGER NOT NULL REFERENCES pdf_function(id), ordinal INTEGER NOT NULL, value INTEGER NOT NULL CHECK (value BETWEEN 0 AND 4294967295));
CREATE TABLE pdf_function_size (id INTEGER PRIMARY KEY, function_id INTEGER NOT NULL REFERENCES pdf_function(id), ordinal INTEGER NOT NULL, value INTEGER NOT NULL);
CREATE TABLE pdf_function_child (id INTEGER PRIMARY KEY, function_id INTEGER NOT NULL REFERENCES pdf_function(id), ordinal INTEGER NOT NULL, child_id INTEGER NOT NULL REFERENCES pdf_function(id));
CREATE TABLE pdf_color_space (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('deviceGray','deviceRgb','deviceCmyk','calGray','calRgb','lab','iccBased','indexed','separation','deviceN','pattern','named')), components INTEGER, profile_id INTEGER REFERENCES pdf_artifact_reference(id), hival INTEGER, palette BLOB, name TEXT, alternate_id INTEGER REFERENCES pdf_color_space(id), tint_transform_id INTEGER REFERENCES pdf_function(id), attributes_id INTEGER REFERENCES pdf_cos_value(id), range_present INTEGER CHECK (range_present IN (0,1)), black_present INTEGER CHECK (black_present IN (0,1)), gamma_present INTEGER CHECK (gamma_present IN (0,1)), matrix_present INTEGER CHECK (matrix_present IN (0,1)));
CREATE TABLE pdf_color_real (id INTEGER PRIMARY KEY, color_space_id INTEGER NOT NULL REFERENCES pdf_color_space(id), role TEXT NOT NULL CHECK (role IN ('whitePoint','blackPoint','gamma','matrix','range')), ordinal INTEGER NOT NULL, value REAL, value_bits INTEGER, value_class TEXT CHECK (value_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_color_name (id INTEGER PRIMARY KEY, color_space_id INTEGER NOT NULL REFERENCES pdf_color_space(id), ordinal INTEGER NOT NULL, name TEXT NOT NULL);
CREATE TABLE pdf_font_encoding (id INTEGER PRIMARY KEY, base TEXT CHECK (base IN ('standard','winAnsi','macRoman','macExpert')));
CREATE TABLE pdf_encoding_difference (id INTEGER PRIMARY KEY, encoding_id INTEGER NOT NULL REFERENCES pdf_font_encoding(id), ordinal INTEGER NOT NULL, code INTEGER NOT NULL, glyph TEXT NOT NULL);
CREATE TABLE pdf_font_descriptor (id INTEGER PRIMARY KEY, font_name TEXT NOT NULL, flags INTEGER NOT NULL, bbox_llx REAL, bbox_lly REAL, bbox_urx REAL, bbox_ury REAL, italic_angle REAL, ascent REAL, descent REAL, cap_height REAL, stem_v REAL, stem_h REAL, x_height REAL, leading REAL, avg_width REAL, max_width REAL, missing_width REAL, font_family TEXT, font_stretch TEXT, font_weight REAL, char_set TEXT, extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id), bbox_llx_bits INTEGER, bbox_llx_class TEXT CHECK (bbox_llx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_lly_bits INTEGER, bbox_lly_class TEXT CHECK (bbox_lly_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_urx_bits INTEGER, bbox_urx_class TEXT CHECK (bbox_urx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_ury_bits INTEGER, bbox_ury_class TEXT CHECK (bbox_ury_class IN ('finite','positiveInfinity','negativeInfinity','nan')), italic_angle_bits INTEGER, italic_angle_class TEXT CHECK (italic_angle_class IN ('finite','positiveInfinity','negativeInfinity','nan')), ascent_bits INTEGER, ascent_class TEXT CHECK (ascent_class IN ('finite','positiveInfinity','negativeInfinity','nan')), descent_bits INTEGER, descent_class TEXT CHECK (descent_class IN ('finite','positiveInfinity','negativeInfinity','nan')), cap_height_bits INTEGER, cap_height_class TEXT CHECK (cap_height_class IN ('finite','positiveInfinity','negativeInfinity','nan')), stem_v_bits INTEGER, stem_v_class TEXT CHECK (stem_v_class IN ('finite','positiveInfinity','negativeInfinity','nan')), stem_h_bits INTEGER, stem_h_class TEXT CHECK (stem_h_class IN ('finite','positiveInfinity','negativeInfinity','nan')), x_height_bits INTEGER, x_height_class TEXT CHECK (x_height_class IN ('finite','positiveInfinity','negativeInfinity','nan')), leading_bits INTEGER, leading_class TEXT CHECK (leading_class IN ('finite','positiveInfinity','negativeInfinity','nan')), avg_width_bits INTEGER, avg_width_class TEXT CHECK (avg_width_class IN ('finite','positiveInfinity','negativeInfinity','nan')), max_width_bits INTEGER, max_width_class TEXT CHECK (max_width_class IN ('finite','positiveInfinity','negativeInfinity','nan')), missing_width_bits INTEGER, missing_width_class TEXT CHECK (missing_width_class IN ('finite','positiveInfinity','negativeInfinity','nan')), font_weight_bits INTEGER, font_weight_class TEXT CHECK (font_weight_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_font_program (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, artifact_reference_id INTEGER NOT NULL REFERENCES pdf_artifact_reference(id));
CREATE TABLE pdf_to_unicode (id INTEGER PRIMARY KEY, byte_width INTEGER NOT NULL);
CREATE TABLE pdf_unicode_mapping (id INTEGER PRIMARY KEY, cmap_id INTEGER NOT NULL REFERENCES pdf_to_unicode(id), ordinal INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('char','range')), code INTEGER, low INTEGER, high INTEGER, text TEXT NOT NULL);
CREATE TABLE pdf_cmap (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('predefined','embedded')), name TEXT NOT NULL, vertical INTEGER CHECK (vertical IN (0,1)), use_cmap TEXT);
CREATE TABLE pdf_codespace_range (id INTEGER PRIMARY KEY, cmap_id INTEGER NOT NULL REFERENCES pdf_cmap(id), ordinal INTEGER NOT NULL, byte_width INTEGER NOT NULL, low INTEGER NOT NULL, high INTEGER NOT NULL);
CREATE TABLE pdf_cid_mapping (id INTEGER PRIMARY KEY, cmap_id INTEGER NOT NULL REFERENCES pdf_cmap(id), ordinal INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('char','range')), code INTEGER, low INTEGER, high INTEGER, cid INTEGER NOT NULL);
CREATE TABLE pdf_cid_font (id INTEGER PRIMARY KEY, true_type INTEGER NOT NULL CHECK (true_type IN (0,1)), base_font TEXT NOT NULL, registry TEXT NOT NULL, ordering TEXT NOT NULL, supplement INTEGER NOT NULL, descriptor_id INTEGER NOT NULL REFERENCES pdf_font_descriptor(id), default_width REAL, default_vertical_y REAL, default_vertical_width REAL, gid_kind TEXT CHECK (gid_kind IN ('identity','map')), gid_count INTEGER CHECK(gid_count>=0), program_id INTEGER REFERENCES pdf_font_program(id), extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id), default_width_bits INTEGER, default_width_class TEXT CHECK (default_width_class IN ('finite','positiveInfinity','negativeInfinity','nan')), default_vertical_y_bits INTEGER, default_vertical_y_class TEXT CHECK (default_vertical_y_class IN ('finite','positiveInfinity','negativeInfinity','nan')), default_vertical_width_bits INTEGER, default_vertical_width_class TEXT CHECK (default_vertical_width_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_cid_width_run (id INTEGER PRIMARY KEY, font_id INTEGER NOT NULL REFERENCES pdf_cid_font(id), ordinal INTEGER NOT NULL, start_cid INTEGER NOT NULL);
CREATE TABLE pdf_cid_width (id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES pdf_cid_width_run(id), ordinal INTEGER NOT NULL, width REAL, width_bits INTEGER, width_class TEXT CHECK (width_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_cid_vertical_run (id INTEGER PRIMARY KEY, font_id INTEGER NOT NULL REFERENCES pdf_cid_font(id), ordinal INTEGER NOT NULL, start_cid INTEGER NOT NULL);
CREATE TABLE pdf_cid_vertical_metric (id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES pdf_cid_vertical_run(id), ordinal INTEGER NOT NULL, w1y REAL, vx REAL, vy REAL, w1y_bits INTEGER, w1y_class TEXT CHECK (w1y_class IN ('finite','positiveInfinity','negativeInfinity','nan')), vx_bits INTEGER, vx_class TEXT CHECK (vx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), vy_bits INTEGER, vy_class TEXT CHECK (vy_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_font (id INTEGER PRIMARY KEY, resource_name TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('type1','trueType','type3','type0')), base_font TEXT, encoding_id INTEGER REFERENCES pdf_font_encoding(id), first_char INTEGER, descriptor_id INTEGER REFERENCES pdf_font_descriptor(id), program_id INTEGER REFERENCES pdf_font_program(id), matrix_a REAL, matrix_b REAL, matrix_c REAL, matrix_d REAL, matrix_e REAL, matrix_f REAL, bbox_llx REAL, bbox_lly REAL, bbox_urx REAL, bbox_ury REAL, cmap_id INTEGER REFERENCES pdf_cmap(id), descendant_id INTEGER REFERENCES pdf_cid_font(id), to_unicode_id INTEGER REFERENCES pdf_to_unicode(id), extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id), matrix_a_bits INTEGER, matrix_a_class TEXT CHECK (matrix_a_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_b_bits INTEGER, matrix_b_class TEXT CHECK (matrix_b_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_c_bits INTEGER, matrix_c_class TEXT CHECK (matrix_c_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_d_bits INTEGER, matrix_d_class TEXT CHECK (matrix_d_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_e_bits INTEGER, matrix_e_class TEXT CHECK (matrix_e_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_f_bits INTEGER, matrix_f_class TEXT CHECK (matrix_f_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_llx_bits INTEGER, bbox_llx_class TEXT CHECK (bbox_llx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_lly_bits INTEGER, bbox_lly_class TEXT CHECK (bbox_lly_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_urx_bits INTEGER, bbox_urx_class TEXT CHECK (bbox_urx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_ury_bits INTEGER, bbox_ury_class TEXT CHECK (bbox_ury_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_font_width (id INTEGER PRIMARY KEY, font_id INTEGER NOT NULL REFERENCES pdf_font(id), ordinal INTEGER NOT NULL, width REAL, width_bits INTEGER, width_class TEXT CHECK (width_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_char_proc (id INTEGER PRIMARY KEY, font_id INTEGER NOT NULL REFERENCES pdf_font(id), ordinal INTEGER NOT NULL, name TEXT NOT NULL, content_id INTEGER NOT NULL REFERENCES pdf_content(id));
CREATE TABLE pdf_content (id INTEGER PRIMARY KEY);
CREATE TABLE pdf_operation (id INTEGER PRIMARY KEY, content_id INTEGER NOT NULL REFERENCES pdf_content(id), ordinal INTEGER NOT NULL, kind TEXT NOT NULL, line_width REAL, line_cap TEXT, line_join TEXT, miter_limit REAL, dash_phase REAL, rendering_intent TEXT, flatness REAL, ext_g_state TEXT, x1 REAL, y1 REAL, x2 REAL, y2 REAL, x3 REAL, y3 REAL, width REAL, height REAL, char_spacing REAL, word_spacing REAL, horizontal_scale REAL, leading REAL, font_name TEXT, font_size REAL, text_rendering_mode INTEGER, text_rise REAL, tx REAL, ty REAL, text_kind TEXT, text_value TEXT, text_code_count INTEGER, glyph_wx REAL, glyph_wy REAL, bbox_llx REAL, bbox_lly REAL, bbox_urx REAL, bbox_ury REAL, color_space_name TEXT, pattern_name TEXT, gray REAL, red REAL, green REAL, blue REAL, cyan REAL, magenta REAL, yellow REAL, black REAL, shading_name TEXT, xobject_name TEXT, marked_tag TEXT, property_kind TEXT, property_name TEXT, property_dictionary_id INTEGER REFERENCES pdf_cos_value(id), inline_image_id INTEGER REFERENCES pdf_inline_image(id), unknown_operator TEXT, line_width_bits INTEGER, line_width_class TEXT CHECK (line_width_class IN ('finite','positiveInfinity','negativeInfinity','nan')), miter_limit_bits INTEGER, miter_limit_class TEXT CHECK (miter_limit_class IN ('finite','positiveInfinity','negativeInfinity','nan')), dash_phase_bits INTEGER, dash_phase_class TEXT CHECK (dash_phase_class IN ('finite','positiveInfinity','negativeInfinity','nan')), flatness_bits INTEGER, flatness_class TEXT CHECK (flatness_class IN ('finite','positiveInfinity','negativeInfinity','nan')), x1_bits INTEGER, x1_class TEXT CHECK (x1_class IN ('finite','positiveInfinity','negativeInfinity','nan')), y1_bits INTEGER, y1_class TEXT CHECK (y1_class IN ('finite','positiveInfinity','negativeInfinity','nan')), x2_bits INTEGER, x2_class TEXT CHECK (x2_class IN ('finite','positiveInfinity','negativeInfinity','nan')), y2_bits INTEGER, y2_class TEXT CHECK (y2_class IN ('finite','positiveInfinity','negativeInfinity','nan')), x3_bits INTEGER, x3_class TEXT CHECK (x3_class IN ('finite','positiveInfinity','negativeInfinity','nan')), y3_bits INTEGER, y3_class TEXT CHECK (y3_class IN ('finite','positiveInfinity','negativeInfinity','nan')), width_bits INTEGER, width_class TEXT CHECK (width_class IN ('finite','positiveInfinity','negativeInfinity','nan')), height_bits INTEGER, height_class TEXT CHECK (height_class IN ('finite','positiveInfinity','negativeInfinity','nan')), char_spacing_bits INTEGER, char_spacing_class TEXT CHECK (char_spacing_class IN ('finite','positiveInfinity','negativeInfinity','nan')), word_spacing_bits INTEGER, word_spacing_class TEXT CHECK (word_spacing_class IN ('finite','positiveInfinity','negativeInfinity','nan')), horizontal_scale_bits INTEGER, horizontal_scale_class TEXT CHECK (horizontal_scale_class IN ('finite','positiveInfinity','negativeInfinity','nan')), leading_bits INTEGER, leading_class TEXT CHECK (leading_class IN ('finite','positiveInfinity','negativeInfinity','nan')), font_size_bits INTEGER, font_size_class TEXT CHECK (font_size_class IN ('finite','positiveInfinity','negativeInfinity','nan')), text_rise_bits INTEGER, text_rise_class TEXT CHECK (text_rise_class IN ('finite','positiveInfinity','negativeInfinity','nan')), tx_bits INTEGER, tx_class TEXT CHECK (tx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), ty_bits INTEGER, ty_class TEXT CHECK (ty_class IN ('finite','positiveInfinity','negativeInfinity','nan')), glyph_wx_bits INTEGER, glyph_wx_class TEXT CHECK (glyph_wx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), glyph_wy_bits INTEGER, glyph_wy_class TEXT CHECK (glyph_wy_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_llx_bits INTEGER, bbox_llx_class TEXT CHECK (bbox_llx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_lly_bits INTEGER, bbox_lly_class TEXT CHECK (bbox_lly_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_urx_bits INTEGER, bbox_urx_class TEXT CHECK (bbox_urx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_ury_bits INTEGER, bbox_ury_class TEXT CHECK (bbox_ury_class IN ('finite','positiveInfinity','negativeInfinity','nan')), gray_bits INTEGER, gray_class TEXT CHECK (gray_class IN ('finite','positiveInfinity','negativeInfinity','nan')), red_bits INTEGER, red_class TEXT CHECK (red_class IN ('finite','positiveInfinity','negativeInfinity','nan')), green_bits INTEGER, green_class TEXT CHECK (green_class IN ('finite','positiveInfinity','negativeInfinity','nan')), blue_bits INTEGER, blue_class TEXT CHECK (blue_class IN ('finite','positiveInfinity','negativeInfinity','nan')), cyan_bits INTEGER, cyan_class TEXT CHECK (cyan_class IN ('finite','positiveInfinity','negativeInfinity','nan')), magenta_bits INTEGER, magenta_class TEXT CHECK (magenta_class IN ('finite','positiveInfinity','negativeInfinity','nan')), yellow_bits INTEGER, yellow_class TEXT CHECK (yellow_class IN ('finite','positiveInfinity','negativeInfinity','nan')), black_bits INTEGER, black_class TEXT CHECK (black_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_operation_matrix (id INTEGER PRIMARY KEY REFERENCES pdf_operation(id), a REAL, b REAL, c REAL, d REAL, e REAL, f REAL, a_bits INTEGER, a_class TEXT CHECK (a_class IN ('finite','positiveInfinity','negativeInfinity','nan')), b_bits INTEGER, b_class TEXT CHECK (b_class IN ('finite','positiveInfinity','negativeInfinity','nan')), c_bits INTEGER, c_class TEXT CHECK (c_class IN ('finite','positiveInfinity','negativeInfinity','nan')), d_bits INTEGER, d_class TEXT CHECK (d_class IN ('finite','positiveInfinity','negativeInfinity','nan')), e_bits INTEGER, e_class TEXT CHECK (e_class IN ('finite','positiveInfinity','negativeInfinity','nan')), f_bits INTEGER, f_class TEXT CHECK (f_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_operation_component (id INTEGER PRIMARY KEY, operation_id INTEGER NOT NULL REFERENCES pdf_operation(id), ordinal INTEGER NOT NULL, value REAL, value_bits INTEGER, value_class TEXT CHECK (value_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_text_array_item (id INTEGER PRIMARY KEY, operation_id INTEGER NOT NULL REFERENCES pdf_operation(id), ordinal INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('text','codes','adjust')), text TEXT, code_count INTEGER, adjustment REAL, adjustment_bits INTEGER, adjustment_class TEXT CHECK (adjustment_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_unknown_operand (id INTEGER PRIMARY KEY, operation_id INTEGER NOT NULL REFERENCES pdf_operation(id), ordinal INTEGER NOT NULL, value_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));
CREATE TABLE pdf_inline_image (id INTEGER PRIMARY KEY, width INTEGER NOT NULL, height INTEGER NOT NULL, bits_per_component INTEGER NOT NULL, color_space_id INTEGER REFERENCES pdf_color_space(id), image_mask INTEGER NOT NULL CHECK (image_mask IN (0,1)), interpolate INTEGER NOT NULL CHECK (interpolate IN (0,1)), body_kind TEXT NOT NULL CHECK(body_kind IN ('samples','artifact')), artifact_reference_id INTEGER REFERENCES pdf_artifact_reference(id), extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));
CREATE TABLE pdf_inline_decode (id INTEGER PRIMARY KEY, image_id INTEGER NOT NULL REFERENCES pdf_inline_image(id), ordinal INTEGER NOT NULL, value REAL, value_bits INTEGER, value_class TEXT CHECK (value_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_image (id INTEGER PRIMARY KEY, resource_name TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, color_space_id INTEGER REFERENCES pdf_color_space(id), bits_per_component INTEGER NOT NULL, image_mask INTEGER NOT NULL CHECK (image_mask IN (0,1)), interpolate INTEGER NOT NULL CHECK (interpolate IN (0,1)), body_kind TEXT NOT NULL CHECK(body_kind IN ('samples','artifact')), artifact_reference_id INTEGER REFERENCES pdf_artifact_reference(id), soft_mask TEXT, soft_mask_in_data INTEGER, mask_kind TEXT CHECK (mask_kind IN ('stencil','colorKey')), stencil_image TEXT, matte_present INTEGER NOT NULL CHECK (matte_present IN (0,1)), intent TEXT, optional_content TEXT, struct_parent INTEGER, extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));
CREATE TABLE pdf_image_real (id INTEGER PRIMARY KEY, image_id INTEGER NOT NULL REFERENCES pdf_image(id), role TEXT NOT NULL CHECK (role IN ('decode','matte')), ordinal INTEGER NOT NULL, value REAL, value_bits INTEGER, value_class TEXT CHECK (value_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_image_color_key (id INTEGER PRIMARY KEY, image_id INTEGER NOT NULL REFERENCES pdf_image(id), ordinal INTEGER NOT NULL, value INTEGER NOT NULL);
CREATE TABLE pdf_transparency_group (id INTEGER PRIMARY KEY, color_space_id INTEGER REFERENCES pdf_color_space(id), isolated INTEGER NOT NULL CHECK (isolated IN (0,1)), knockout INTEGER NOT NULL CHECK (knockout IN (0,1)));
CREATE TABLE pdf_form_xobject (id INTEGER PRIMARY KEY, resource_name TEXT NOT NULL, bbox_llx REAL, bbox_lly REAL, bbox_urx REAL, bbox_ury REAL, matrix_a REAL, matrix_b REAL, matrix_c REAL, matrix_d REAL, matrix_e REAL, matrix_f REAL, content_id INTEGER NOT NULL REFERENCES pdf_content(id), group_id INTEGER REFERENCES pdf_transparency_group(id), optional_content TEXT, struct_parent INTEGER, extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id), bbox_llx_bits INTEGER, bbox_llx_class TEXT CHECK (bbox_llx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_lly_bits INTEGER, bbox_lly_class TEXT CHECK (bbox_lly_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_urx_bits INTEGER, bbox_urx_class TEXT CHECK (bbox_urx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_ury_bits INTEGER, bbox_ury_class TEXT CHECK (bbox_ury_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_a_bits INTEGER, matrix_a_class TEXT CHECK (matrix_a_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_b_bits INTEGER, matrix_b_class TEXT CHECK (matrix_b_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_c_bits INTEGER, matrix_c_class TEXT CHECK (matrix_c_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_d_bits INTEGER, matrix_d_class TEXT CHECK (matrix_d_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_e_bits INTEGER, matrix_e_class TEXT CHECK (matrix_e_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_f_bits INTEGER, matrix_f_class TEXT CHECK (matrix_f_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_ext_g_state (id INTEGER PRIMARY KEY, resource_name TEXT NOT NULL, line_width REAL, line_cap TEXT, line_join TEXT, miter_limit REAL, dash_phase REAL, rendering_intent TEXT, overprint_stroke INTEGER CHECK (overprint_stroke IN (0,1)), overprint_fill INTEGER CHECK (overprint_fill IN (0,1)), overprint_mode INTEGER, font_name TEXT, font_size REAL, blend_present INTEGER NOT NULL CHECK (blend_present IN (0,1)), soft_mask_kind TEXT CHECK (soft_mask_kind IN ('none','alpha','luminosity')), soft_mask_group TEXT, backdrop_present INTEGER CHECK (backdrop_present IN (0,1)), transfer_id INTEGER REFERENCES pdf_function(id), stroke_alpha REAL, fill_alpha REAL, alpha_is_shape INTEGER CHECK (alpha_is_shape IN (0,1)), stroke_adjust INTEGER CHECK (stroke_adjust IN (0,1)), flatness REAL, smoothness REAL, text_knockout INTEGER CHECK (text_knockout IN (0,1)), extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id), line_width_bits INTEGER, line_width_class TEXT CHECK (line_width_class IN ('finite','positiveInfinity','negativeInfinity','nan')), miter_limit_bits INTEGER, miter_limit_class TEXT CHECK (miter_limit_class IN ('finite','positiveInfinity','negativeInfinity','nan')), dash_phase_bits INTEGER, dash_phase_class TEXT CHECK (dash_phase_class IN ('finite','positiveInfinity','negativeInfinity','nan')), font_size_bits INTEGER, font_size_class TEXT CHECK (font_size_class IN ('finite','positiveInfinity','negativeInfinity','nan')), stroke_alpha_bits INTEGER, stroke_alpha_class TEXT CHECK (stroke_alpha_class IN ('finite','positiveInfinity','negativeInfinity','nan')), fill_alpha_bits INTEGER, fill_alpha_class TEXT CHECK (fill_alpha_class IN ('finite','positiveInfinity','negativeInfinity','nan')), flatness_bits INTEGER, flatness_class TEXT CHECK (flatness_class IN ('finite','positiveInfinity','negativeInfinity','nan')), smoothness_bits INTEGER, smoothness_class TEXT CHECK (smoothness_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_g_state_real (id INTEGER PRIMARY KEY, state_id INTEGER NOT NULL REFERENCES pdf_ext_g_state(id), role TEXT NOT NULL CHECK (role IN ('dash','backdrop')), ordinal INTEGER NOT NULL, value REAL, value_bits INTEGER, value_class TEXT CHECK (value_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_blend_mode (id INTEGER PRIMARY KEY, state_id INTEGER NOT NULL REFERENCES pdf_ext_g_state(id), ordinal INTEGER NOT NULL, name TEXT NOT NULL);
CREATE TABLE pdf_shading (id INTEGER PRIMARY KEY, resource_name TEXT NOT NULL, color_space_id INTEGER NOT NULL REFERENCES pdf_color_space(id), kind TEXT NOT NULL CHECK (kind IN ('functionBased','axial','radial','mesh')), background_present INTEGER NOT NULL CHECK (background_present IN (0,1)), bbox_llx REAL, bbox_lly REAL, bbox_urx REAL, bbox_ury REAL, anti_alias INTEGER NOT NULL CHECK (anti_alias IN (0,1)), extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id), bbox_llx_bits INTEGER, bbox_llx_class TEXT CHECK (bbox_llx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_lly_bits INTEGER, bbox_lly_class TEXT CHECK (bbox_lly_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_urx_bits INTEGER, bbox_urx_class TEXT CHECK (bbox_urx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_ury_bits INTEGER, bbox_ury_class TEXT CHECK (bbox_ury_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_shading_background (id INTEGER PRIMARY KEY, shading_id INTEGER NOT NULL REFERENCES pdf_shading(id), ordinal INTEGER NOT NULL, value REAL, value_bits INTEGER, value_class TEXT CHECK (value_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_function_shading (id INTEGER PRIMARY KEY REFERENCES pdf_shading(id), domain_xmin REAL, domain_xmax REAL, domain_ymin REAL, domain_ymax REAL, matrix_a REAL, matrix_b REAL, matrix_c REAL, matrix_d REAL, matrix_e REAL, matrix_f REAL, function_id INTEGER NOT NULL REFERENCES pdf_function(id), domain_xmin_bits INTEGER, domain_xmin_class TEXT CHECK (domain_xmin_class IN ('finite','positiveInfinity','negativeInfinity','nan')), domain_xmax_bits INTEGER, domain_xmax_class TEXT CHECK (domain_xmax_class IN ('finite','positiveInfinity','negativeInfinity','nan')), domain_ymin_bits INTEGER, domain_ymin_class TEXT CHECK (domain_ymin_class IN ('finite','positiveInfinity','negativeInfinity','nan')), domain_ymax_bits INTEGER, domain_ymax_class TEXT CHECK (domain_ymax_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_a_bits INTEGER, matrix_a_class TEXT CHECK (matrix_a_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_b_bits INTEGER, matrix_b_class TEXT CHECK (matrix_b_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_c_bits INTEGER, matrix_c_class TEXT CHECK (matrix_c_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_d_bits INTEGER, matrix_d_class TEXT CHECK (matrix_d_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_e_bits INTEGER, matrix_e_class TEXT CHECK (matrix_e_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_f_bits INTEGER, matrix_f_class TEXT CHECK (matrix_f_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_axial_shading (id INTEGER PRIMARY KEY REFERENCES pdf_shading(id), x0 REAL, y0 REAL, x1 REAL, y1 REAL, domain_start REAL, domain_end REAL, function_id INTEGER NOT NULL REFERENCES pdf_function(id), extend_start INTEGER NOT NULL CHECK (extend_start IN (0,1)), extend_end INTEGER NOT NULL CHECK (extend_end IN (0,1)), x0_bits INTEGER, x0_class TEXT CHECK (x0_class IN ('finite','positiveInfinity','negativeInfinity','nan')), y0_bits INTEGER, y0_class TEXT CHECK (y0_class IN ('finite','positiveInfinity','negativeInfinity','nan')), x1_bits INTEGER, x1_class TEXT CHECK (x1_class IN ('finite','positiveInfinity','negativeInfinity','nan')), y1_bits INTEGER, y1_class TEXT CHECK (y1_class IN ('finite','positiveInfinity','negativeInfinity','nan')), domain_start_bits INTEGER, domain_start_class TEXT CHECK (domain_start_class IN ('finite','positiveInfinity','negativeInfinity','nan')), domain_end_bits INTEGER, domain_end_class TEXT CHECK (domain_end_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_radial_shading (id INTEGER PRIMARY KEY REFERENCES pdf_shading(id), x0 REAL, y0 REAL, r0 REAL, x1 REAL, y1 REAL, r1 REAL, domain_start REAL, domain_end REAL, function_id INTEGER NOT NULL REFERENCES pdf_function(id), extend_start INTEGER NOT NULL CHECK (extend_start IN (0,1)), extend_end INTEGER NOT NULL CHECK (extend_end IN (0,1)), x0_bits INTEGER, x0_class TEXT CHECK (x0_class IN ('finite','positiveInfinity','negativeInfinity','nan')), y0_bits INTEGER, y0_class TEXT CHECK (y0_class IN ('finite','positiveInfinity','negativeInfinity','nan')), r0_bits INTEGER, r0_class TEXT CHECK (r0_class IN ('finite','positiveInfinity','negativeInfinity','nan')), x1_bits INTEGER, x1_class TEXT CHECK (x1_class IN ('finite','positiveInfinity','negativeInfinity','nan')), y1_bits INTEGER, y1_class TEXT CHECK (y1_class IN ('finite','positiveInfinity','negativeInfinity','nan')), r1_bits INTEGER, r1_class TEXT CHECK (r1_class IN ('finite','positiveInfinity','negativeInfinity','nan')), domain_start_bits INTEGER, domain_start_class TEXT CHECK (domain_start_class IN ('finite','positiveInfinity','negativeInfinity','nan')), domain_end_bits INTEGER, domain_end_class TEXT CHECK (domain_end_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_mesh_shading (id INTEGER PRIMARY KEY REFERENCES pdf_shading(id), shading_type INTEGER NOT NULL, bits_per_coordinate INTEGER NOT NULL, bits_per_component INTEGER NOT NULL, bits_per_flag INTEGER, vertices_per_row INTEGER, function_id INTEGER REFERENCES pdf_function(id), artifact_reference_id INTEGER NOT NULL REFERENCES pdf_artifact_reference(id));
CREATE TABLE pdf_mesh_decode (id INTEGER PRIMARY KEY, shading_id INTEGER NOT NULL REFERENCES pdf_mesh_shading(id), ordinal INTEGER NOT NULL, value REAL, value_bits INTEGER, value_class TEXT CHECK (value_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_pattern (id INTEGER PRIMARY KEY, resource_name TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('tiling','shading')), matrix_a REAL, matrix_b REAL, matrix_c REAL, matrix_d REAL, matrix_e REAL, matrix_f REAL, extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id), matrix_a_bits INTEGER, matrix_a_class TEXT CHECK (matrix_a_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_b_bits INTEGER, matrix_b_class TEXT CHECK (matrix_b_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_c_bits INTEGER, matrix_c_class TEXT CHECK (matrix_c_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_d_bits INTEGER, matrix_d_class TEXT CHECK (matrix_d_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_e_bits INTEGER, matrix_e_class TEXT CHECK (matrix_e_class IN ('finite','positiveInfinity','negativeInfinity','nan')), matrix_f_bits INTEGER, matrix_f_class TEXT CHECK (matrix_f_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_tiling_pattern (id INTEGER PRIMARY KEY REFERENCES pdf_pattern(id), paint_type INTEGER NOT NULL, tiling_type INTEGER NOT NULL, bbox_llx REAL, bbox_lly REAL, bbox_urx REAL, bbox_ury REAL, x_step REAL, y_step REAL, content_id INTEGER NOT NULL REFERENCES pdf_content(id), bbox_llx_bits INTEGER, bbox_llx_class TEXT CHECK (bbox_llx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_lly_bits INTEGER, bbox_lly_class TEXT CHECK (bbox_lly_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_urx_bits INTEGER, bbox_urx_class TEXT CHECK (bbox_urx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bbox_ury_bits INTEGER, bbox_ury_class TEXT CHECK (bbox_ury_class IN ('finite','positiveInfinity','negativeInfinity','nan')), x_step_bits INTEGER, x_step_class TEXT CHECK (x_step_class IN ('finite','positiveInfinity','negativeInfinity','nan')), y_step_bits INTEGER, y_step_class TEXT CHECK (y_step_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_shading_pattern (id INTEGER PRIMARY KEY REFERENCES pdf_pattern(id), shading TEXT NOT NULL, ext_g_state TEXT);
CREATE TABLE pdf_date (id INTEGER PRIMARY KEY, year INTEGER NOT NULL, month INTEGER NOT NULL, day INTEGER NOT NULL, hour INTEGER NOT NULL, minute INTEGER NOT NULL, second INTEGER NOT NULL, offset_minutes INTEGER);
CREATE TABLE pdf_document_info (id INTEGER PRIMARY KEY, title TEXT, author TEXT, subject TEXT, keywords TEXT, creator TEXT, producer TEXT, creation_date_id INTEGER REFERENCES pdf_date(id), modification_date_id INTEGER REFERENCES pdf_date(id), trapped TEXT, extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));
CREATE TABLE pdf_embedded_file (id INTEGER PRIMARY KEY, resource_name TEXT NOT NULL, file_name TEXT NOT NULL, description TEXT, mime_type TEXT, data BLOB NOT NULL, creation_date_id INTEGER REFERENCES pdf_date(id), modification_date_id INTEGER REFERENCES pdf_date(id), relationship TEXT, listed INTEGER NOT NULL CHECK (listed IN (0,1)));
CREATE TABLE pdf_output_intent (id INTEGER PRIMARY KEY, subtype TEXT NOT NULL, condition_identifier TEXT NOT NULL, condition TEXT, registry_name TEXT, info TEXT, profile_id INTEGER REFERENCES pdf_artifact_reference(id));
CREATE TABLE pdf_encryption (id INTEGER PRIMARY KEY, algorithm TEXT NOT NULL CHECK (algorithm IN ('rc4_40','rc4_128','aes128','aes256')), permissions INTEGER NOT NULL, user_password TEXT NOT NULL, owner_password TEXT, encrypt_metadata INTEGER NOT NULL CHECK (encrypt_metadata IN (0,1)));
CREATE TABLE pdf_viewer_preferences (id INTEGER PRIMARY KEY, hide_toolbar INTEGER NOT NULL CHECK (hide_toolbar IN (0,1)), hide_menubar INTEGER NOT NULL CHECK (hide_menubar IN (0,1)), hide_window_ui INTEGER NOT NULL CHECK (hide_window_ui IN (0,1)), fit_window INTEGER NOT NULL CHECK (fit_window IN (0,1)), center_window INTEGER NOT NULL CHECK (center_window IN (0,1)), display_doc_title INTEGER NOT NULL CHECK (display_doc_title IN (0,1)), non_full_screen_page_mode TEXT, direction TEXT, view_area TEXT, view_clip TEXT, print_area TEXT, print_clip TEXT, print_scaling TEXT, duplex TEXT, pick_tray_by_pdf_size INTEGER NOT NULL CHECK (pick_tray_by_pdf_size IN (0,1)), num_copies INTEGER, extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));
CREATE TABLE pdf_print_page_range (id INTEGER PRIMARY KEY, preferences_id INTEGER NOT NULL REFERENCES pdf_viewer_preferences(id), ordinal INTEGER NOT NULL, page INTEGER NOT NULL);
CREATE TABLE pdf_mark_info (id INTEGER PRIMARY KEY, marked INTEGER NOT NULL CHECK (marked IN (0,1)), user_properties INTEGER NOT NULL CHECK (user_properties IN (0,1)), suspects INTEGER NOT NULL CHECK (suspects IN (0,1)));
CREATE TABLE pdf_destination (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('page','remotePage','named')), page_index INTEGER, name TEXT, fit_kind TEXT CHECK (fit_kind IN ('xyz','fit','fitHorizontal','fitVertical','fitRectangle','fitBoundingBox','fitBoundingBoxHorizontal','fitBoundingBoxVertical')), left REAL, top REAL, zoom REAL, rect_llx REAL, rect_lly REAL, rect_urx REAL, rect_ury REAL, left_bits INTEGER, left_class TEXT CHECK (left_class IN ('finite','positiveInfinity','negativeInfinity','nan')), top_bits INTEGER, top_class TEXT CHECK (top_class IN ('finite','positiveInfinity','negativeInfinity','nan')), zoom_bits INTEGER, zoom_class TEXT CHECK (zoom_class IN ('finite','positiveInfinity','negativeInfinity','nan')), rect_llx_bits INTEGER, rect_llx_class TEXT CHECK (rect_llx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), rect_lly_bits INTEGER, rect_lly_class TEXT CHECK (rect_lly_class IN ('finite','positiveInfinity','negativeInfinity','nan')), rect_urx_bits INTEGER, rect_urx_class TEXT CHECK (rect_urx_class IN ('finite','positiveInfinity','negativeInfinity','nan')), rect_ury_bits INTEGER, rect_ury_class TEXT CHECK (rect_ury_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_file_specification (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('path','embedded')), value TEXT NOT NULL);
CREATE TABLE pdf_action (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, destination_id INTEGER REFERENCES pdf_destination(id), file_id INTEGER REFERENCES pdf_file_specification(id), new_window INTEGER CHECK (new_window IN (0,1)), thread INTEGER, uri TEXT, is_map INTEGER CHECK (is_map IN (0,1)), sound TEXT, volume REAL, synchronous INTEGER CHECK (synchronous IN (0,1)), repeat INTEGER CHECK (repeat IN (0,1)), mix INTEGER CHECK (mix IN (0,1)), movie_annotation TEXT, movie_operation TEXT, hide INTEGER CHECK (hide IN (0,1)), name TEXT, submit_url TEXT, flags INTEGER, javascript_source TEXT, entries_id INTEGER REFERENCES pdf_cos_value(id), preserve_radio_buttons INTEGER CHECK (preserve_radio_buttons IN (0,1)), unknown_subtype TEXT, volume_bits INTEGER, volume_class TEXT CHECK (volume_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_action_name (id INTEGER PRIMARY KEY, action_id INTEGER NOT NULL REFERENCES pdf_action(id), ordinal INTEGER NOT NULL, name TEXT NOT NULL);
CREATE TABLE pdf_action_next (id INTEGER PRIMARY KEY, action_id INTEGER NOT NULL REFERENCES pdf_action(id), ordinal INTEGER NOT NULL, next_id INTEGER NOT NULL REFERENCES pdf_action(id));
CREATE TABLE pdf_outline (id INTEGER PRIMARY KEY, title TEXT NOT NULL, destination_id INTEGER REFERENCES pdf_destination(id), action_id INTEGER REFERENCES pdf_action(id), red REAL, green REAL, blue REAL, italic INTEGER NOT NULL CHECK (italic IN (0,1)), bold INTEGER NOT NULL CHECK (bold IN (0,1)), open INTEGER NOT NULL CHECK (open IN (0,1)), extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id), red_bits INTEGER, red_class TEXT CHECK (red_class IN ('finite','positiveInfinity','negativeInfinity','nan')), green_bits INTEGER, green_class TEXT CHECK (green_class IN ('finite','positiveInfinity','negativeInfinity','nan')), blue_bits INTEGER, blue_class TEXT CHECK (blue_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_outline_child (id INTEGER PRIMARY KEY, outline_id INTEGER NOT NULL REFERENCES pdf_outline(id), ordinal INTEGER NOT NULL, child_id INTEGER NOT NULL REFERENCES pdf_outline(id));
CREATE TABLE pdf_named_destination (id INTEGER PRIMARY KEY, name TEXT NOT NULL, destination_id INTEGER NOT NULL REFERENCES pdf_destination(id));
CREATE TABLE pdf_page_label (id INTEGER PRIMARY KEY, start_index INTEGER NOT NULL, style TEXT CHECK (style IN ('decimal','romanUpper','romanLower','lettersUpper','lettersLower')), prefix TEXT, start INTEGER NOT NULL);
CREATE TABLE pdf_open_action (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('destination','action')), destination_id INTEGER REFERENCES pdf_destination(id), action_id INTEGER REFERENCES pdf_action(id));

CREATE TABLE pdf_appearance_entry(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,form TEXT);
CREATE TABLE pdf_appearance_state(id INTEGER PRIMARY KEY,entry_id INTEGER NOT NULL REFERENCES pdf_appearance_entry(id),ordinal INTEGER NOT NULL,state TEXT NOT NULL,form TEXT NOT NULL);
CREATE TABLE pdf_appearance(id INTEGER PRIMARY KEY,normal_id INTEGER NOT NULL REFERENCES pdf_appearance_entry(id),rollover_id INTEGER REFERENCES pdf_appearance_entry(id),down_id INTEGER REFERENCES pdf_appearance_entry(id));
CREATE TABLE pdf_annotation_border(id INTEGER PRIMARY KEY,width REAL,style TEXT,dash_present INTEGER NOT NULL,radius_x REAL,radius_y REAL, width_bits INTEGER, width_class TEXT CHECK (width_class IN ('finite','positiveInfinity','negativeInfinity','nan')), radius_x_bits INTEGER, radius_x_class TEXT CHECK (radius_x_class IN ('finite','positiveInfinity','negativeInfinity','nan')), radius_y_bits INTEGER, radius_y_class TEXT CHECK (radius_y_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_border_dash(id INTEGER PRIMARY KEY,border_id INTEGER NOT NULL REFERENCES pdf_annotation_border(id),ordinal INTEGER NOT NULL,value REAL, value_bits INTEGER, value_class TEXT CHECK (value_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_annotation_markup(id INTEGER PRIMARY KEY,title TEXT,popup_high INTEGER,popup_low INTEGER,opacity REAL,rich_contents TEXT,creation_date_id INTEGER REFERENCES pdf_date(id),reply_high INTEGER,reply_low INTEGER,subject TEXT,reply_type TEXT,intent TEXT, opacity_bits INTEGER, opacity_class TEXT CHECK (opacity_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_annotation(id INTEGER PRIMARY KEY,rect_left REAL,rect_bottom REAL,rect_right REAL,rect_top REAL,contents TEXT,name TEXT,modified TEXT,flags INTEGER NOT NULL,border_id INTEGER REFERENCES pdf_annotation_border(id),appearance_id INTEGER REFERENCES pdf_appearance(id),appearance_state TEXT,markup_id INTEGER REFERENCES pdf_annotation_markup(id),optional_content TEXT,struct_parent INTEGER,extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id),detail_id INTEGER NOT NULL REFERENCES pdf_annotation_detail(id), rect_left_bits INTEGER, rect_left_class TEXT CHECK (rect_left_class IN ('finite','positiveInfinity','negativeInfinity','nan')), rect_bottom_bits INTEGER, rect_bottom_class TEXT CHECK (rect_bottom_class IN ('finite','positiveInfinity','negativeInfinity','nan')), rect_right_bits INTEGER, rect_right_class TEXT CHECK (rect_right_class IN ('finite','positiveInfinity','negativeInfinity','nan')), rect_top_bits INTEGER, rect_top_class TEXT CHECK (rect_top_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_annotation_real(id INTEGER PRIMARY KEY,annotation_id INTEGER NOT NULL REFERENCES pdf_annotation(id),ordinal INTEGER NOT NULL,value REAL, value_bits INTEGER, value_class TEXT CHECK (value_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_annotation_detail(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,state TEXT,state_model TEXT,action_id INTEGER REFERENCES pdf_action(id),destination_id INTEGER REFERENCES pdf_destination(id),highlight TEXT,default_appearance TEXT,quadding INTEGER,line_ending TEXT,rich_text TEXT,ending_start TEXT,ending_end TEXT,leader_length REAL,caption INTEGER,icon TEXT,symbol TEXT,parent_high INTEGER,parent_low INTEGER,open INTEGER,file_id INTEGER REFERENCES pdf_file_specification(id),sound_id INTEGER REFERENCES pdf_cos_value(id),title TEXT,movie_id INTEGER REFERENCES pdf_cos_value(id),activation_id INTEGER REFERENCES pdf_cos_value(id),field TEXT,characteristics_id INTEGER REFERENCES pdf_cos_value(id),additional_actions_id INTEGER REFERENCES pdf_cos_value(id),mark_style TEXT,colorants_id INTEGER REFERENCES pdf_cos_value(id),entries_id INTEGER REFERENCES pdf_cos_value(id),fixed_print_id INTEGER REFERENCES pdf_cos_value(id),overlay_text TEXT,repeat INTEGER,subtype TEXT,interior_present INTEGER,callout_present INTEGER,point_0 REAL,point_1 REAL,point_2 REAL,point_3 REAL, leader_length_bits INTEGER, leader_length_class TEXT CHECK (leader_length_class IN ('finite','positiveInfinity','negativeInfinity','nan')), point_0_bits INTEGER, point_0_class TEXT CHECK (point_0_class IN ('finite','positiveInfinity','negativeInfinity','nan')), point_1_bits INTEGER, point_1_class TEXT CHECK (point_1_class IN ('finite','positiveInfinity','negativeInfinity','nan')), point_2_bits INTEGER, point_2_class TEXT CHECK (point_2_class IN ('finite','positiveInfinity','negativeInfinity','nan')), point_3_bits INTEGER, point_3_class TEXT CHECK (point_3_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_annotation_kind_real(id INTEGER PRIMARY KEY,detail_id INTEGER NOT NULL REFERENCES pdf_annotation_detail(id),ordinal INTEGER NOT NULL,role TEXT NOT NULL,value REAL, value_bits INTEGER, value_class TEXT CHECK (value_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_annotation_ink_path(id INTEGER PRIMARY KEY,detail_id INTEGER NOT NULL REFERENCES pdf_annotation_detail(id),ordinal INTEGER NOT NULL);
CREATE TABLE pdf_annotation_ink_coordinate(id INTEGER PRIMARY KEY,path_id INTEGER NOT NULL REFERENCES pdf_annotation_ink_path(id),ordinal INTEGER NOT NULL,value REAL, value_bits INTEGER, value_class TEXT CHECK (value_class IN ('finite','positiveInfinity','negativeInfinity','nan')));

CREATE TABLE pdf_form_field(id INTEGER PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,flags INTEGER NOT NULL,alternate_name TEXT,mapping_name TEXT,default_appearance TEXT,quadding INTEGER,value TEXT,default_value TEXT,max_length INTEGER,rich_value TEXT,top_index INTEGER,signature_id INTEGER REFERENCES pdf_cos_value(id),additional_actions_id INTEGER NOT NULL REFERENCES pdf_cos_value(id),extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));
CREATE TABLE pdf_field_name(id INTEGER PRIMARY KEY,field_id INTEGER NOT NULL REFERENCES pdf_form_field(id),ordinal INTEGER NOT NULL,role TEXT NOT NULL,value TEXT NOT NULL);
CREATE TABLE pdf_choice_option(id INTEGER PRIMARY KEY,field_id INTEGER NOT NULL REFERENCES pdf_form_field(id),ordinal INTEGER NOT NULL,export TEXT NOT NULL,display TEXT NOT NULL);
CREATE TABLE pdf_field_widget(id INTEGER PRIMARY KEY,field_id INTEGER NOT NULL REFERENCES pdf_form_field(id),ordinal INTEGER NOT NULL,page_index INTEGER NOT NULL,annotation_index INTEGER NOT NULL);
CREATE TABLE pdf_field_child(id INTEGER PRIMARY KEY,field_id INTEGER NOT NULL REFERENCES pdf_form_field(id),ordinal INTEGER NOT NULL,child_id INTEGER NOT NULL REFERENCES pdf_form_field(id));
CREATE TABLE pdf_acro_form(id INTEGER PRIMARY KEY,need_appearances INTEGER NOT NULL,signature_flags INTEGER NOT NULL,default_appearance TEXT,quadding INTEGER,extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));
CREATE TABLE pdf_acro_field(id INTEGER PRIMARY KEY,acro_id INTEGER NOT NULL REFERENCES pdf_acro_form(id),ordinal INTEGER NOT NULL,field_id INTEGER NOT NULL REFERENCES pdf_form_field(id));
CREATE TABLE pdf_acro_font(id INTEGER PRIMARY KEY,acro_id INTEGER NOT NULL REFERENCES pdf_acro_form(id),ordinal INTEGER NOT NULL,name TEXT NOT NULL);
CREATE TABLE pdf_optional_content(id INTEGER PRIMARY KEY,name TEXT,base_state_off INTEGER NOT NULL,extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));
CREATE TABLE pdf_optional_group(id INTEGER PRIMARY KEY,optional_id INTEGER NOT NULL REFERENCES pdf_optional_content(id),ordinal INTEGER NOT NULL,resource TEXT NOT NULL,name TEXT NOT NULL,usage_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));
CREATE TABLE pdf_optional_group_intent(id INTEGER PRIMARY KEY,group_id INTEGER NOT NULL REFERENCES pdf_optional_group(id),ordinal INTEGER NOT NULL,name TEXT NOT NULL);
CREATE TABLE pdf_optional_name(id INTEGER PRIMARY KEY,optional_id INTEGER NOT NULL REFERENCES pdf_optional_content(id),ordinal INTEGER NOT NULL,role TEXT NOT NULL,name TEXT NOT NULL);
CREATE TABLE pdf_optional_order(id INTEGER PRIMARY KEY,optional_id INTEGER NOT NULL REFERENCES pdf_optional_content(id),ordinal INTEGER NOT NULL,value_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));

CREATE TABLE pdf_page(id INTEGER PRIMARY KEY,media_left REAL,media_bottom REAL,media_right REAL,media_top REAL,crop_left REAL,crop_bottom REAL,crop_right REAL,crop_top REAL,bleed_left REAL,bleed_bottom REAL,bleed_right REAL,bleed_top REAL,trim_left REAL,trim_bottom REAL,trim_right REAL,trim_top REAL,art_left REAL,art_bottom REAL,art_right REAL,art_top REAL,rotate INTEGER NOT NULL,user_unit REAL,content_id INTEGER NOT NULL REFERENCES pdf_content(id),group_id INTEGER REFERENCES pdf_transparency_group(id),thumbnail TEXT,struct_parents INTEGER,transition_id INTEGER REFERENCES pdf_cos_value(id),duration REAL,metadata TEXT,additional_actions_id INTEGER NOT NULL REFERENCES pdf_cos_value(id),extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id), media_left_bits INTEGER, media_left_class TEXT CHECK (media_left_class IN ('finite','positiveInfinity','negativeInfinity','nan')), media_bottom_bits INTEGER, media_bottom_class TEXT CHECK (media_bottom_class IN ('finite','positiveInfinity','negativeInfinity','nan')), media_right_bits INTEGER, media_right_class TEXT CHECK (media_right_class IN ('finite','positiveInfinity','negativeInfinity','nan')), media_top_bits INTEGER, media_top_class TEXT CHECK (media_top_class IN ('finite','positiveInfinity','negativeInfinity','nan')), crop_left_bits INTEGER, crop_left_class TEXT CHECK (crop_left_class IN ('finite','positiveInfinity','negativeInfinity','nan')), crop_bottom_bits INTEGER, crop_bottom_class TEXT CHECK (crop_bottom_class IN ('finite','positiveInfinity','negativeInfinity','nan')), crop_right_bits INTEGER, crop_right_class TEXT CHECK (crop_right_class IN ('finite','positiveInfinity','negativeInfinity','nan')), crop_top_bits INTEGER, crop_top_class TEXT CHECK (crop_top_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bleed_left_bits INTEGER, bleed_left_class TEXT CHECK (bleed_left_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bleed_bottom_bits INTEGER, bleed_bottom_class TEXT CHECK (bleed_bottom_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bleed_right_bits INTEGER, bleed_right_class TEXT CHECK (bleed_right_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bleed_top_bits INTEGER, bleed_top_class TEXT CHECK (bleed_top_class IN ('finite','positiveInfinity','negativeInfinity','nan')), trim_left_bits INTEGER, trim_left_class TEXT CHECK (trim_left_class IN ('finite','positiveInfinity','negativeInfinity','nan')), trim_bottom_bits INTEGER, trim_bottom_class TEXT CHECK (trim_bottom_class IN ('finite','positiveInfinity','negativeInfinity','nan')), trim_right_bits INTEGER, trim_right_class TEXT CHECK (trim_right_class IN ('finite','positiveInfinity','negativeInfinity','nan')), trim_top_bits INTEGER, trim_top_class TEXT CHECK (trim_top_class IN ('finite','positiveInfinity','negativeInfinity','nan')), art_left_bits INTEGER, art_left_class TEXT CHECK (art_left_class IN ('finite','positiveInfinity','negativeInfinity','nan')), art_bottom_bits INTEGER, art_bottom_class TEXT CHECK (art_bottom_class IN ('finite','positiveInfinity','negativeInfinity','nan')), art_right_bits INTEGER, art_right_class TEXT CHECK (art_right_class IN ('finite','positiveInfinity','negativeInfinity','nan')), art_top_bits INTEGER, art_top_class TEXT CHECK (art_top_class IN ('finite','positiveInfinity','negativeInfinity','nan')), user_unit_bits INTEGER, user_unit_class TEXT CHECK (user_unit_class IN ('finite','positiveInfinity','negativeInfinity','nan')), duration_bits INTEGER, duration_class TEXT CHECK (duration_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE pdf_page_annotation(id INTEGER PRIMARY KEY,page_id INTEGER NOT NULL REFERENCES pdf_page(id),ordinal INTEGER NOT NULL,annotation_id INTEGER NOT NULL REFERENCES pdf_annotation(id));
CREATE TABLE pdf_named_color(id INTEGER PRIMARY KEY,name TEXT NOT NULL,color_id INTEGER NOT NULL REFERENCES pdf_color_space(id));
CREATE TABLE pdf_named_properties(id INTEGER PRIMARY KEY,name TEXT NOT NULL,entries_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));
CREATE TABLE pdf_indirect_object(id INTEGER PRIMARY KEY,number INTEGER NOT NULL,generation INTEGER NOT NULL,value_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));
CREATE TABLE pdf_document(id INTEGER PRIMARY KEY CHECK(id=1),schema TEXT NOT NULL,declared_version TEXT NOT NULL,acro_id INTEGER REFERENCES pdf_acro_form(id),optional_id INTEGER REFERENCES pdf_optional_content(id),page_layout TEXT,page_mode TEXT,preferences_id INTEGER REFERENCES pdf_viewer_preferences(id),open_action_id INTEGER REFERENCES pdf_open_action(id),language TEXT,mark_id INTEGER REFERENCES pdf_mark_info(id),metadata TEXT,document_id_first BLOB,document_id_second BLOB,encryption_id INTEGER REFERENCES pdf_encryption(id),info_id INTEGER NOT NULL REFERENCES pdf_document_info(id),catalog_extra_id INTEGER NOT NULL REFERENCES pdf_cos_value(id),trailer_id INTEGER NOT NULL REFERENCES pdf_cos_value(id));
CREATE TABLE pdf_document_page(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,page_id INTEGER NOT NULL REFERENCES pdf_page(id));
CREATE TABLE pdf_document_font(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,font_id INTEGER NOT NULL REFERENCES pdf_font(id));
CREATE TABLE pdf_document_image(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,image_id INTEGER NOT NULL REFERENCES pdf_image(id));
CREATE TABLE pdf_document_form(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,form_id INTEGER NOT NULL REFERENCES pdf_form_xobject(id));
CREATE TABLE pdf_document_state(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,state_id INTEGER NOT NULL REFERENCES pdf_ext_g_state(id));
CREATE TABLE pdf_document_shading(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,shading_id INTEGER NOT NULL REFERENCES pdf_shading(id));
CREATE TABLE pdf_document_pattern(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,pattern_id INTEGER NOT NULL REFERENCES pdf_pattern(id));
CREATE TABLE pdf_document_color(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,color_id INTEGER NOT NULL REFERENCES pdf_named_color(id));
CREATE TABLE pdf_document_properties(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,properties_id INTEGER NOT NULL REFERENCES pdf_named_properties(id));
CREATE TABLE pdf_document_outline(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,outline_id INTEGER NOT NULL REFERENCES pdf_outline(id));
CREATE TABLE pdf_document_destination(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,destination_id INTEGER NOT NULL REFERENCES pdf_named_destination(id));
CREATE TABLE pdf_document_label(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,label_id INTEGER NOT NULL REFERENCES pdf_page_label(id));
CREATE TABLE pdf_document_file(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,file_id INTEGER NOT NULL REFERENCES pdf_embedded_file(id));
CREATE TABLE pdf_document_intent(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,intent_id INTEGER NOT NULL REFERENCES pdf_output_intent(id));
CREATE TABLE pdf_document_object(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,object_id INTEGER NOT NULL REFERENCES pdf_indirect_object(id));

CREATE TABLE pdf_operation_code (id INTEGER PRIMARY KEY, operation_id INTEGER NOT NULL REFERENCES pdf_operation(id), ordinal INTEGER NOT NULL, code INTEGER NOT NULL CHECK (code >= 0 AND code <= 4294967295));
CREATE TABLE pdf_array_item_code (id INTEGER PRIMARY KEY, item_id INTEGER NOT NULL REFERENCES pdf_text_array_item(id), ordinal INTEGER NOT NULL, code INTEGER NOT NULL CHECK (code >= 0 AND code <= 4294967295));

CREATE TABLE pdf_graph_identity(id INTEGER PRIMARY KEY,object_number INTEGER NOT NULL CHECK(object_number BETWEEN 0 AND 4294967295),object_generation INTEGER NOT NULL CHECK(object_generation BETWEEN 0 AND 65535));
CREATE TABLE pdf_graph_path(id INTEGER PRIMARY KEY,identity_id INTEGER NOT NULL REFERENCES pdf_graph_identity(id),ordinal INTEGER NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('entry','item')),entry_key TEXT,item_index INTEGER CHECK(item_index>=0),CHECK((kind='entry' AND entry_key IS NOT NULL AND item_index IS NULL) OR (kind='item' AND entry_key IS NULL AND item_index IS NOT NULL)));
CREATE TABLE pdf_stream_role(id INTEGER PRIMARY KEY,identity_id INTEGER NOT NULL REFERENCES pdf_graph_identity(id),kind TEXT NOT NULL CHECK(kind IN ('operators','sampledWords','calculatorProgram','unicodeMap','characterMap','fontProgram','image','metadataText','attachmentBytes','paletteComponents','glyphIds','referenceBody')),operators_id INTEGER REFERENCES pdf_content(id),sample_count INTEGER CHECK(sample_count>=0),code TEXT,unicode_id INTEGER REFERENCES pdf_to_unicode(id),cmap_id INTEGER REFERENCES pdf_cmap(id),program_id INTEGER REFERENCES pdf_font_program(id),image_id INTEGER REFERENCES pdf_image(id),metadata_text TEXT,attachment_data BLOB, palette_components BLOB, glyph_count INTEGER CHECK(glyph_count >= 0), artifact_reference_id INTEGER REFERENCES pdf_artifact_reference(id));
CREATE TABLE pdf_stream_role_sample(id INTEGER PRIMARY KEY,role_id INTEGER NOT NULL REFERENCES pdf_stream_role(id),ordinal INTEGER NOT NULL,word INTEGER NOT NULL CHECK(word BETWEEN 0 AND 4294967295));
CREATE TABLE pdf_stream_role_dependency(id INTEGER PRIMARY KEY,role_id INTEGER NOT NULL REFERENCES pdf_stream_role(id),ordinal INTEGER NOT NULL,identity_id INTEGER NOT NULL REFERENCES pdf_graph_identity(id));
CREATE TABLE pdf_document_role(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES pdf_document(id),ordinal INTEGER NOT NULL,role_id INTEGER NOT NULL REFERENCES pdf_stream_role(id));

CREATE TABLE pdf_stream_role_glyph(id INTEGER PRIMARY KEY,role_id INTEGER NOT NULL REFERENCES pdf_stream_role(id),ordinal INTEGER NOT NULL,glyph INTEGER NOT NULL CHECK(glyph BETWEEN 0 AND 65535));

CREATE TABLE pdf_image_sample (id INTEGER PRIMARY KEY, owner INTEGER NOT NULL REFERENCES pdf_image(id), ordinal INTEGER NOT NULL, value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 65535));

CREATE TABLE pdf_cid_glyph (id INTEGER PRIMARY KEY, cid_font_id INTEGER NOT NULL REFERENCES pdf_cid_font(id), ordinal INTEGER NOT NULL, glyph INTEGER NOT NULL CHECK(glyph BETWEEN 0 AND 65535));

CREATE TABLE pdf_inline_sample (id INTEGER PRIMARY KEY, inline_image_id INTEGER NOT NULL REFERENCES pdf_inline_image(id), ordinal INTEGER NOT NULL, value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 65535));
